Lemma stepA lo hi byo raA : runA lo hi byo raA -> lo <= v <= hi -> -64 <= byo <= -49 -> L5.ra_ok raA ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, INV M2 md2 LK2 Aw2 cr2 k2 1 -> inregs R2 sp (PMSPA.o_v AD fb) v -> csk R2 ->
