Lemma stepB8 (fxq : FPState) Rq Mq mdq LKq Awq crq kq : v <= 255 ->
  INV Mq mdq LKq Awq crq kq 1 -> inregs Rq sp (PMSPA.o_v AD fb) v -> csk Rq -> getr Rq (reg 20) = Z_to_bv 64 ((PMSPA.o_v AD fb + 8) / 8 + SBL) ->
